const lockers = document.querySelector('#locker-numbers');

document.querySelector('#show-lockers').addEventListener('click', () => {
  lockers.replaceChildren();
  for (let number = 101; number <= 103; number += 1) {
    const item = document.createElement('li');
    item.textContent = '储物柜 ' + number;
    lockers.append(item);
  }
});
